# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.1/engra-0.2.1-macos-arm64.tar.gz"
      sha256 "51ac62b57d00cb3facdaeb1212235c31161029c6aa149a7b55fa9f0c91552a37"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.1/engra-0.2.1-macos-x64.tar.gz"
      sha256 "008a10bca4137dc2c92ea728fd7768eadd7fc89efe401b674da09da97c2febd1"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.1/engra-0.2.1-linux-arm64.tar.gz"
      sha256 "e6b1885f134210e83283bb5ef42b8bb006e5b8a44942e4dce75fb96e0478ba47"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.1/engra-0.2.1-linux-x64.tar.gz"
      sha256 "2105b2164a944b0682f3afd2712007cdf70680c8d56c7848b7825a13afec958c"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
